class Solution {
  solveNQueens(n) {
    const result = [];
    const board = new Array(n).fill(0).map(() => new Array(n).fill("."));
    const cols = new Set();
    const diag1 = new Set();
    const diag2 = new Set();
    const place = (row) => {
