class Solution {
  pairSum(head) {
    let slow = head;
    let fast = head;
    while (fast !== null && fast.next !== null) {
      slow = slow.next;
      fast = fast.next.next;
    }
    let prev = null;
    let current = slow;
    while (current !== null) {
      const next = current.next;
      current.next = prev;
      prev = current;
      current = next;
    }
    let left = head;
    let right = prev;
    let best = 0;
    while (right !== null) {
      best = Math.max(best, left.val + right.val);
      left = left.next;
      right = right.next;
    }
    return best;
  }
}
